style.css:
@-moz-document domain("open.spotify.com") {
html,
    body {
        background-color: #050508 !important;
    }

    body {
        background-image:
            linear-gradient(
                rgba(0, 0, 0, 0.45),
                rgba(0, 0, 0, 0.45)
            ),
            url("https://www.image2url.com/r2/default/images/1788350372875-3ab4087f-9b76-488a-8e51-783d3f4f984f.jpeg") !important;

        background-size: cover !important;
        background-position: center center !important;
        background-repeat: no-repeat !important;
        background-attachment: fixed !important;
    }

    #main,
    main {
        background: transparent !important;
    }

    nav {
        background: rgba(3, 3, 10, 0.90) !important;
        border-right: 1px solid rgba(125, 60, 255, 0.35) !important;
        box-shadow: 5px 0 30px rgba(100, 30, 255, 0.20) !important;
    }

    footer {
        background: rgba(3, 3, 10, 0.94) !important;
        border-top: 1px solid rgba(125, 60, 255, 0.35) !important;
        box-shadow: 0 -5px 30px rgba(100, 30, 255, 0.20) !important;
    }

    input {
        background: rgba(5, 5, 15, 0.85) !important;
        border: 1px solid rgba(125, 60, 255, 0.35) !important;
        color: white !important;
    }

    [aria-current="page"] {
        background: rgba(100, 40, 255, 0.25) !important;
        box-shadow: inset 3px 0 #8b4dff !important;
    }

    button:hover {
        filter: drop-shadow(0 0 8px #7b3fff) !important;
    }

    ::-webkit-scrollbar {
        width: 8px !important;
    }

    ::-webkit-scrollbar-track {
        background: #050508 !important;
    }

    ::-webkit-scrollbar-thumb {
        background: linear-gradient(
            #7b3fff,
            #00d9ff
        ) !important;
        border-radius: 10px !important;
    }
}
